package org.codex.nfsugpreview;
import android.app.*;import android.os.*;import java.io.*;import java.nio.*;import java.nio.file.*;import java.security.*;import java.util.*;import java.util.concurrent.atomic.AtomicReference;import org.json.*;
public final class WallHistoryInstrumentation extends Instrumentation {
 void ok(boolean value,String why){if(!value)throw new AssertionError(why);}
 String hex(byte[] data){StringBuilder s=new StringBuilder();for(byte b:data)s.append(String.format("%02x",b&255));return s.toString();}
 String sha(byte[] data)throws Exception{return hex(MessageDigest.getInstance("SHA-256").digest(data));}
 byte[] copy(ByteBuffer b){byte[] raw=new byte[b.remaining()];b.get(raw);return raw;}
 @Override public void onCreate(Bundle args){super.onCreate(args);start();}
 @Override public void onStart(){Bundle result=new Bundle();try{
  Path dir=getTargetContext().getFilesDir().toPath();byte[] state=Files.readAllBytes(dir.resolve("wall-test.state"));List<String> frames=Files.readAllLines(dir.resolve("wall-frames.txt"));Map<Long,String> refs=new HashMap<>();for(String line:Files.readAllLines(dir.resolve("wall-owners.txt"))){String[] t=line.split(" ");refs.put(Long.parseLong(t[0]),t[1]);}
  Map<Long,String> seen=new HashMap<>();Set<Long> matched=new HashSet<>();int older=0,display=0,whole=0,split=0;long[] last=null;byte[] retained=null;String retainedHash=null;long audioFrames=0;MessageDigest sound=MessageDigest.getInstance("SHA-256");ByteBuffer pixels=ByteBuffer.allocateDirect(NativeCore.FRAME_BYTES);short[] pcm=new short[8192];
  NativeCore core=new NativeCore(dir.resolve("wall-test.gba").toString());try{
   ok(!core.captureWallHistory(true),"Wall enable without capture");ok(core.loadCheckpoint(state)&&core.capture(true)&&core.captureLayers(true)&&core.captureSourceWorld(true)&&core.captureWallHistory(true)&&core.captureWallHistory(true),"Wall enable");long initial=core.timing()[2];
   for(int i=0;i<600;i++){
    ok(core.step(1|(i>=60&&i<120?16:0)|(i>=480&&i<540?32:0))==1,"Step");ok(core.frame(pixels),"Frame");pixels.position(0);MessageDigest image=MessageDigest.getInstance("SHA-256");image.update(pixels);ok(hex(image.digest()).equals(frames.get(i)),"Original frame "+i);long[] clock=core.timing();ok(clock[0]==16777216&&clock[1]==280896&&clock[2]==initial+i+1&&clock[3]==i+1,"Timing");
    int n;while((n=core.audio(pcm))>0){audioFrames+=n;byte[] raw=new byte[n*4];for(int k=0;k<n*2;k++){raw[k*2]=(byte)pcm[k];raw[k*2+1]=(byte)(pcm[k]>>8);}sound.update(raw);}
    long[] stats=core.wallHistoryStats();ok(stats!=null&&stats[0]==1&&stats[1]==0,"Wall source failure");byte[] bound=core.capturedSourceScene();if(bound!=null){NativeSceneSnapshot scene=new NativeSceneSnapshot(bound);display++;if(scene.kind==1)whole++;else split++;}
    long[] info=core.captureStats();if(info[6]==0||seen.containsKey(info[7]))continue;byte[] packet=core.capturedPacket();ByteBuffer h=ByteBuffer.wrap(packet).order(ByteOrder.LITTLE_ENDIAN);long serial=h.getInt(16)&0xffffffffL,begin=h.getInt(20)&0xffffffffL,end=h.getInt(24)&0xffffffffL;
    if(last!=null){byte[] old=core.capturedWallHistory(last[0],last[1],last[2],last[3]);ok(old!=null&&sha(old).equals(seen.get(last[1])),"Older wall owner changed");older++;}
    byte[] raw=core.capturedWallHistory(info[1],serial,begin,end);ok(raw!=null,"Missing wall owner "+serial);String hash=sha(raw);seen.put(serial,hash);last=new long[]{info[1],serial,begin,end};if(retained==null){retained=raw;retainedHash=hash;}if(refs.containsKey(serial)){ok(hash.equals(refs.get(serial)),"PC wall bytes differ "+serial);NativeWallHistory history=new NativeWallHistory(raw);ok(history.epoch==info[1],"History epoch");matched.add(serial);}
    ok(core.capturedWallHistory(info[1]+1,serial,begin,end)==null&&core.capturedWallHistory(info[1],serial,begin+1,end)==null,"Stale identity");
   }
   ok(seen.size()==148&&matched.size()==13&&older==147&&display==594&&whole>0&&split>0,"Capture scope "+seen.size()+" matched "+matched.size()+" display "+display);ok(audioFrames==443007&&hex(sound.digest()).equals("eedce61302b062d825e9a26fa1d8399f0a7c29eaf4319e33a3d71eedd40be33e"),"Audio");long[] key=last;
   AtomicReference<Throwable> failure=new AtomicReference<>();Thread wrong=new Thread(()->{try{core.capturedWallHistory(key[0],key[1],key[2],key[3]);failure.set(new AssertionError("Wrong thread accepted"));}catch(IllegalStateException expectedFailure){}});wrong.start();wrong.join();ok(failure.get()==null,"Owner thread");
   ok(core.capturedWallHistory(key[0],-1,key[2],key[3])==null&&core.capturedWallHistory(key[0],key[1],key[2],0x100000000L)==null,"JNI identity range");ok(core.loadCheckpoint(state)&&core.capturedWallHistory(key[0],key[1],key[2],key[3])==null&&core.wallHistoryStats()[3]==0,"Reset stale wall");
   for(int i=0;i<80;i++){ok(core.step(1|(i>=60?16:0))==1&&core.frame(pixels),"Post reset frame");pixels.position(0);MessageDigest image=MessageDigest.getInstance("SHA-256");image.update(pixels);ok(hex(image.digest()).equals(frames.get(i)),"Post reset image");}
   ok(core.wallHistoryStats()[3]>0&&core.wallHistoryStats()[1]==0,"Reset capture resumes");ok(core.captureWallHistory(false)&&core.capturedWallHistory(key[0],key[1],key[2],key[3])==null&&core.captureWallHistory(true)&&core.capture(false),"Disable/re-enable/detach");
  }finally{core.close();}
  ok(retained!=null&&sha(retained).equals(retainedHash),"Caller-owned bytes after close");try{core.wallHistoryStats();throw new AssertionError("Closed core accepted");}catch(IllegalStateException expectedFailure){}
  JSONObject report=new JSONObject();report.put("result","PASS_ANDROID_WALL_HISTORY_JNI");report.put("original_rgba_frames",600);report.put("post_reset_original_frames",80);report.put("original_timing",true);report.put("audio_frames",audioFrames);report.put("wall_owners",seen.size());report.put("pc_identical_wall_owners",matched.size());report.put("older_owner_immutable_checks",older);report.put("source_display_snapshots",display);report.put("whole",whole);report.put("split",split);report.put("reset_disable_owner_range_close_guards",true);report.put("diagnostic_setup_required",false);report.put("api",Build.VERSION.SDK_INT);report.put("gpu_rendering",false);report.put("real_time_pacing",false);try(FileOutputStream f=getTargetContext().openFileOutput("wall-history-jni-report.json",0)){f.write(report.toString(2).getBytes("UTF-8"));}result.putString("stream",report.toString());finish(Activity.RESULT_OK,result);
 }catch(Throwable failure){android.util.Log.e("NFSUGWallJNI","Failed",failure);result.putString("stream","FAIL: "+failure);finish(Activity.RESULT_CANCELED,result);}}
}
